window.REC_META = {"repo": "curso-esp32-riego", "subtitle": "Riego autónomo que mira el cielo", "description": "Controlador de riego sobre ESP32-S3 con portal cautivo, cuatro horarios diarios, persistencia en EEPROM y consulta de lluvia a OpenWeatherMap. Un curso completo que va del hotspot al relé que mueve la bomba.", "repo_url": "https://github.com/jmadasme/curso-esp32-riego", "page_url": "https://jmadasme.github.io/curso-esp32-riego/", "poster_text": "Controlador de riego sobre ESP32-S3 con portal cautivo, cuatro horarios diarios, persistencia en EEPROM y consulta de lluvia a OpenWeatherMap. Un curso completo que va del hotspot al relé que mueve la bomba.", "commands": ["arduino-cli compile --fqbn esp32:esp32:esp32s3 .", "arduino-cli upload -p /dev/ttyUSB0 --fqbn esp32:esp32:esp32s3 .", "arduino-cli monitor -p /dev/ttyUSB0 -c baudrate=115200"], "chapters": [{"time": "0:06", "label": "EL PROBLEMA", "title": "Regar aunque llueva"}, {"time": "0:21", "label": "ARQUITECTURA", "title": "Un archivo por responsabilidad"}, {"time": "0:34", "label": "CONFIGURACIÓN", "title": "Todo el estado en una struct"}, {"time": "0:48", "label": "PERSISTENCIA", "title": "Un checksum para no arrancar con basura"}, {"time": "1:00", "label": "CAPTIVE PORTAL", "title": "Configurar sin router"}, {"time": "1:13", "label": "INTERFAZ", "title": "El dashboard se actualiza solo"}, {"time": "1:26", "label": "PROGRAMADOR", "title": "Coincidencia exacta, ventana de un minuto"}, {"time": "1:39", "label": "CLIMA", "title": "Una llamada, una probabilidad"}, {"time": "1:53", "label": "EL RELÉ", "title": "Un máximo que no se negocia"}, {"time": "2:07", "label": "LA DECISIÓN", "title": "Si la API falla, se riega"}, {"time": "2:21", "label": "EL BUCLE", "title": "Tres tareas, ninguna bloqueante"}, {"time": "2:34", "label": "CÓMO EJECUTARLO", "title": "Compilar y cargar el controlador"}], "width": 104, "height": 34, "duration": 174.95, "title": "Curso ESP32 Riego"};
